const MAX_TAGS=8, MAX_LINKS=6;
const cleanTags=tags=>Array.isArray(tags)?tags.slice(0,MAX_TAGS).filter(x=>typeof x?.label==='string').map(x=>({label:x.label.slice(0,28),color:/^#[0-9a-f]{6}$/i.test(x.color)?x.color:'#66a8c7'})):[];
const cleanLinks=links=>Array.isArray(links)?links.slice(0,MAX_LINKS).filter(x=>typeof x?.url==='string').map(x=>({label:String(x.label||'Link').slice(0,32),url:x.url.slice(0,400)})).filter(x=>{try{return new URL(x.url).protocol==='https:';}catch{return false;}}):[];
function avatarContent(extra=''){const p=state.profileData||{};return p.avatarData&&/^data:image\/(?:png|jpe?g|webp|gif);base64,/i.test(p.avatarData)?`<img src="${esc(p.avatarData)}" alt="Foto do perfil" ${extra}>`:esc((p.name||'P').slice(0,1).toUpperCase());}
function noticeCount(){return state.notifications.filter(n=>!n.read).length;}
function renderNotices(){return `<div class="cx-notice-pop ${state.noticeOpen?'open':''}" id="noticePopover" role="region" aria-label="Central de notificações" ${state.noticeOpen?'':'hidden'}><div class="cx-notice-head"><div><strong>Notificações</strong><small>${noticeCount()?`${noticeCount()} não lida(s)`:'Tudo em dia'}</small></div><button data-notice-clear ${state.notifications.length?'':'disabled'}>Limpar todas</button></div><div class="cx-notice-list">${state.notifications.length?state.notifications.map(n=>`<button class="cx-notice-item ${n.read?'':'unread'}" data-notice-open="${esc(n.id)}"><span class="cx-notice-icon">${icon(n.kind==='download'?'download':n.kind==='update'?'package':'info',17)}</span><span><strong>${esc(n.title)}</strong><small>${esc(n.message||'')}</small><time>${new Date(n.at||Date.now()).toLocaleDateString(localeTag())}</time></span></button>`).join(''):`<div class="cx-notice-empty">${icon('bell',28)}<strong>Nenhuma notificação</strong><p>Avisaremos quando um download da Caixota terminar ou houver algo importante.</p></div>`}</div></div>`;}
function refreshNotices(){const host=document.getElementById('noticeHost');if(host){host.innerHTML=renderNotices();translateShell(host,effectiveLanguage());}const trigger=document.querySelector('[data-action="notifications"]');if(trigger){trigger.classList.toggle('has-unread',noticeCount()>0);trigger.setAttribute('aria-expanded',String(state.noticeOpen));trigger.innerHTML=`${icon('bell',19)}${noticeCount()?'<i aria-hidden="true"></i>':''}`;}}
const LEGACY_DEFAULT_DISABLED=new Set(['calculatorEnabled','counterEnabled','formatterEnabled','cleanerEnabled','dateEnabled','listEnabled','sorterEnabled','encoderEnabled','colorEnabled','readerEnabled','passwordEnabled','linkCheckerEnabled','comparerEnabled','qrGeneratorEnabled']);
const localToolLabel=tool=>tool.moduleId?tool.label:t(tool.label,effectiveLanguage());
function isDirectTool(t){return !!(t?.direct||['video','pdf'].includes(t?.category));}
function isContextEnabled(t){return !!t.settingId&&(state.realSettings[t.settingId]===undefined?!LEGACY_DEFAULT_DISABLED.has(t.settingId):state.realSettings[t.settingId]!==false);}
function applyRealSettings(snapshot){
 state.realSettings=snapshot.settings||{};state.usage=snapshot.usage||{};state.profileData=snapshot.profile||{};
 state.favorites=favoritesFromSettings(state.realSettings);
 state.toggled=new Set(tools.filter(isContextEnabled).map(t=>t.id));
 state.recent=recentsFromUsage(state.usage);
 state.ui=normalizeUi(snapshot.ui);
 state.preset=state.ui.theme;state.theme=presetBase(state.preset);
 applyThemeOnly();
}
function applyThemeOnly(){setUiSoundVolume(state.ui.volume);updateBoardGame(state.ui);
 document.documentElement.dataset.theme=state.theme;
 document.documentElement.dataset.preset=state.preset;
 document.documentElement.dataset.quality=state.ui.quality;
 document.documentElement.dataset.effects=state.ui.effects?'on':'off';
 document.documentElement.dataset.font=state.ui.font;
 document.documentElement.style.colorScheme=state.theme;
 document.documentElement.style.setProperty('--v3-effective-font',({system:'system-ui, sans-serif',roboto:'Roboto, Arial, sans-serif',montserrat:'Montserrat, Arial, sans-serif',poppins:'Poppins, Arial, sans-serif',opensans:'\"Open Sans\", Arial, sans-serif',lato:'Lato, Arial, sans-serif',pixel:'\"Lucida Console\", Consolas, monospace',vhs:'VHS, monospace'}[state.ui.font]||'inherit')); 
 moduleAppearance(state.ui);updateModuleRuntime(state.ui);
 const btn=document.querySelector('[data-action="theme"]');
 if(btn){btn.innerHTML=icon(state.theme==='dark'?'sun':'moon',19);btn.title=`Tema: ${THEME_LABELS[state.preset]}`;}
}
async function saveUi(patch){try{state.ui=await updateUi(patch);state.preset=state.ui.theme;state.theme=presetBase(state.preset);applyThemeOnly();updateWorkbenchTheme();}catch(err){toast('Não foi possível salvar: '+err.message);}}

const routePages={music:'Player de Música',board:'Jogos',help:'Ajuda e FAQ',moduletool:'Ferramenta do módulo',shortcuts:'Abrir Site com Atalho',mathgen:'Laboratório de Matemática',dino:'Corrida da Caixotinha',browserutility:'Utilitários do navegador',tool:'Ferramenta',arcade:'Jogos',termo:'Termo',media:'Baixador de Mídia',speedtest:'Teste de Velocidade',modules:'Módulos',dice:'Dados de RPG',home:'Início',tools:'Ferramentas',favorites:'Favoritos',recent:'Recentes',settings:'Configurações',profile:'Perfil',support:'Apoie o projeto'};
