const localeTag=()=>({pt:'pt-BR',en:'en-US',de:'de-DE',es:'es-ES',fr:'fr-FR',it:'it-IT',nl:'nl-NL',ja:'ja-JP',zh:'zh-CN',ru:'ru-RU',ko:'ko-KR',pl:'pl-PL'}[effectiveLanguage()]||'pt-BR');
const getIcon=t=>{if(t.id==='utility-media-downloader')return 'download';if(t.category==='utilities')return 'activity';if(t.id==='generator-wheel'||t.id==='utility-dice')return 'dice';if(t.id==='game-termo')return 'book';if(t.id==='game-pong'||t.id==='game-breakout')return 'activity';if(t.id==='game-mines')return 'grid';if(t.category==='generators') return t.id.includes('wheel')?'dice':t.id.includes('qr')?'qr':'sparkles'; if(t.id==='calculate')return 'calculator';if(t.id==='dictionary')return 'book';if(t.id.includes('markdown')||t.id.includes('notes'))return 'clipboard';return types[t.category]?.icon||'grid';};
const unique=arr=>[...new Set(arr)];
const tag=t=>t.network==='required'?'<span class="meta-tag online"><span class="tag-dot"></span> Internet</span>':t.network==='optional'?'<span class="meta-tag optional"><span class="tag-dot"></span> Opcional</span>':'<span class="meta-tag"><span class="tag-dot"></span> Offline</span>';
const countCat=c=>tools.filter(t=>t.category===c).length;
