function navButton(item){return `<button class="nav-link ${state.page===item.id?'active':''}" data-route="${item.id}" ${state.page===item.id?'aria-current="page"':''}>${icon(item.icon,19)}<span>${item.label}</span>${item.id==='favorites'?`<span class="nav-count">${state.favorites.size}</span>`:''}</button>`;}
function categoryNav(c){const t=types[c];return `<button class="nav-link category-link ${state.page==='tools'&&state.category===c?'active':''}" data-category="${c}"><span class="nav-cat-icon ${t.tint}">${icon(t.icon,16)}</span><span>${t.label}</span><span class="nav-number">${countCat(c)}</span></button>`;}
