document.addEventListener('keydown',e=>{if(state.page==='termo'&&!state.modal&&!state.searchOpen&&!state.tutorialOpen)handleTermoKeydown(e); if(e.key==='Escape'&&['tool','moduletool'].includes(state.page)){e.preventDefault();setCategory(state.toolReturnCategory||'text');return;}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch();return;}if(e.key==='Escape'){if(state.tutorialOpen){finishGameTutorial();return;}if(state.noticeOpen){state.noticeOpen=false;refreshNotices();return;}if(state.localeOpen){state.localeOpen=false;const pop=$('.cx-locale-pop');if(pop)pop.hidden=true;return;}if(state.uploadTarget){closeOverlay();return;}if(state.moduleDialog||state.modal||state.searchOpen){closeOverlay();return;}if(state.mobile){state.mobile=false;mount();return;}}if(e.key==='/'&&!state.searchOpen&&!['INPUT','TEXTAREA'].includes(document.activeElement?.tagName)){e.preventDefault();if(state.page==='tools')$('#catalogSearch')?.focus();else openSearch();}if(e.key==='Enter'&&state.searchOpen&&document.activeElement?.id==='commandInput'){e.preventDefault();let first=$('.command-result');first?.click();}});
window.addEventListener('hashchange',()=>{let hash=location.hash.slice(1);if(hash.startsWith('tool/')){const id=decodeURIComponent(hash.slice(5));if(idmap.has(id)&&state.activeToolId!==id)openTool(id);return;}if(routePages[hash]&&state.page!==hash)setPage(hash);});
let initial=location.hash.slice(1);if(initial.startsWith('tool/')){const id=decodeURIComponent(initial.slice(5));if(idmap.has(id)){state.page='tool';state.activeToolId=id;state.toolReturnCategory=idmap.get(id).category;}}else if(routePages[initial])state.page=initial;
mount();
