chrome.storage.onChanged.addListener((changes,area)=>{if(area==='local'&&changes[MODULE_REVISION_KEY]&&!moduleMutation){refreshModules(true).catch(e=>toast(e.message));}if(area==='local'&&changes[FEATURE_STORAGE_KEY]){state.browserFeatures=normalizeFeatures(changes[FEATURE_STORAGE_KEY].newValue);if(state.page==='browserutility')mount();}if(area==='local'&&changes[NOTICE_KEY]){state.notifications=Array.isArray(changes[NOTICE_KEY].newValue)?changes[NOTICE_KEY].newValue.slice(0,40):[];refreshNotices();}if(area==='local'&&(changes[UI_KEY]||changes[SETTINGS_KEY]||changes.tremUsage||changes.caixotaLocalProfile)){syncFromStorage(!['tool','moduletool'].includes(state.page)).then(()=>{if(state.page==='tool')updateWorkbenchTheme();updateModuleRuntime(state.ui);});}});

// Visual-only interactions: a pointer-following highlight and a restrained button ripple.
// These do not call network services or persist settings.
const labMotionOK = !window.matchMedia('(prefers-reduced-motion: reduce)').matches;
if (labMotionOK) {
  document.addEventListener('pointerdown', e => {
    if (e.button!==0) return;
    const btn=e.target.closest('.button-primary, .button-outline, .button-hero-secondary, .tool-open, .popup-footer button');
    if (!btn || btn.disabled) return;
    const r=btn.getBoundingClientRect();
    const ripple=document.createElement('span');
    ripple.className='cx-ripple';
    ripple.style.left=`${e.clientX-r.left}px`;
    ripple.style.top=`${e.clientY-r.top}px`;
    btn.append(ripple);
    ripple.addEventListener('animationend',()=>ripple.remove(),{once:true});
  }, {passive:true});
}

// Atalhos também podem ser usados quando a página da Caixota está em foco.
// Não capturar enquanto o usuário escreve ou grava um novo atalho.
let siteShortcutCache=[];
function reloadSiteShortcuts(){chrome.storage.local.get(SHORTCUT_KEY).then(d=>{siteShortcutCache=Array.isArray(d[SHORTCUT_KEY])?d[SHORTCUT_KEY].slice(0,50):[];}).catch(()=>{});}
reloadSiteShortcuts();
chrome.storage.onChanged.addListener((changes,area)=>{if(area==='local'&&changes[SHORTCUT_KEY])reloadSiteShortcuts();});
window.addEventListener('keydown',event=>{
 if(!event.isTrusted||event.defaultPrevented||event.repeat||event.target?.closest?.('input,textarea,select,[contenteditable="true"],[role="textbox"],#cxShortcutCapture'))return;
 const chord=chordFromEvent(event);
 if(!chord||!siteShortcutCache.some(x=>x.chord===chord))return;
 event.preventDefault();event.stopPropagation();
 chrome.runtime.sendMessage({type:'CAIXOTA_OPEN_SHORTCUT_SITES',chord}).catch(()=>{});
},true);

// Configurações reais: seletores respeitam o armazenamento antigo.
document.addEventListener('change',e=>{
 const node=e.target;
 if(node.id==='v3Font'){saveUi({font:node.value});return;}
 if(node.id==='v3Quality'){saveUi({quality:node.value});return;}if(node.id==='cxVolume'){const v=Number(node.value);setUiSoundVolume(v);saveUi({volume:v});return;}
 if(node.id==='v3Shortcut'){saveUi({shortcut:node.value});return;}
 if(node.matches('[data-v3-legacy]')&&node.dataset.v3Legacy!=='interfaceLanguage')updateSetting(node.dataset.v3Legacy,node.value);
});

function renderUploadOverlay(){const host=document.getElementById('overlayHost');if(host)host.innerHTML=renderOverlay();}
function cleanupCrop(){if(cropState?.url)URL.revokeObjectURL(cropState.url);cropState=null;}
function cropDialog(){const banner=state.uploadTarget==='banner';return `<div class="overlay-backdrop cx-upload-overlay" data-upload-dismiss><div class="cx-upload-modal cx-crop-modal" role="dialog" aria-modal="true" aria-labelledby="cxCropTitle"><div class="cx-upload-top"><div><span class="overline">AJUSTE A IMAGEM</span><h2 id="cxCropTitle">${banner?'Escolha a parte do banner':'Escolha sua foto'}</h2></div><button class="cx-upload-close" data-profile-upload-close aria-label="Fechar">${icon('x',20)}</button></div><p class="cx-crop-instructions">Arraste a foto para escolher o enquadramento. ${banner?'A área marcada é o que vai aparecer no seu banner.':'O círculo mostra como sua foto vai ficar no perfil.'}</p><div class="cx-crop-stage ${banner?'banner':'avatar'}"><canvas id="cxCropCanvas" width="${banner?900:420}" height="${banner?300:420}" aria-label="Prévia do recorte"></canvas><span class="cx-crop-hint">Arraste para mover</span></div><label class="cx-crop-zoom"><button type="button" data-crop-zoom="-" aria-label="Diminuir zoom">−</button> <input id="cxCropZoom" type="range" min="1" max="3" value="1" step="0.01"> <button type="button" data-crop-zoom="+" aria-label="Aumentar zoom">+</button></label><div class="cx-crop-actions"><button class="button-outline" data-crop-back>Outra imagem</button><button class="button-primary" data-crop-save>${icon('check',18)} Usar este recorte</button></div><small>A imagem ficará somente no seu navegador.</small></div></div>`;}
function cropBounds(){const c=document.getElementById('cxCropCanvas');if(!c||!cropState)return null;const {image,zoom}=cropState;const scale=Math.max(c.width/image.naturalWidth,c.height/image.naturalHeight)*zoom;const w=image.naturalWidth*scale,h=image.naturalHeight*scale;const maxX=Math.max(0,(w-c.width)/2),maxY=Math.max(0,(h-c.height)/2);return {c,scale,w,h,maxX,maxY};}
function drawCrop(){const b=cropBounds();if(!b)return;cropState.dx=Math.max(-b.maxX,Math.min(b.maxX,cropState.dx));cropState.dy=Math.max(-b.maxY,Math.min(b.maxY,cropState.dy));const context=b.c.getContext('2d');context.clearRect(0,0,b.c.width,b.c.height);context.imageSmoothingQuality='high';context.drawImage(cropState.image,(b.c.width-b.w)/2+cropState.dx,(b.c.height-b.h)/2+cropState.dy,b.w,b.h);}
async function processProfileImage(file,target){if(!file||!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>4*1024*1024)throw Error('Use PNG, JPEG ou WebP de até 4 MB.');cleanupCrop();const url=URL.createObjectURL(file);try{const image=new Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(Error('Não consegui abrir essa imagem.'));image.src=url;});if(image.naturalWidth>16000||image.naturalHeight>16000)throw Error('Essa imagem é grande demais.');cropState={file,url,image,dx:0,dy:0,zoom:1,target};renderUploadOverlay();requestAnimationFrame(drawCrop);}catch(e){URL.revokeObjectURL(url);throw e;}}
async function saveProfileCrop(){const b=cropBounds();if(!b||!cropState)return;const w=cropState.target==='banner'?1500:512,h=cropState.target==='banner'?500:512,canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;const context=canvas.getContext('2d');context.imageSmoothingQuality='high';const k=w/b.c.width;context.drawImage(cropState.image,((b.c.width-b.w)/2+cropState.dx)*k,((b.c.height-b.h)/2+cropState.dy)*k,b.w*k,b.h*k);const imageData=canvas.toDataURL('image/webp',cropState.target==='banner'?.78:.82),key=cropState.target==='banner'?'bannerData':'avatarData';await chrome.storage.local.set({caixotaLocalProfile:{...state.profileData,[key]:imageData}});const target=cropState.target;cleanupCrop();state.uploadTarget=null;await syncFromStorage(true);toast(target==='banner'?'Banner recortado e salvo!':'Foto recortada e salva!');}
document.addEventListener('change',async e=>{if(e.target.id!=='cxImageUpload')return;try{await processProfileImage(e.target.files?.[0],state.uploadTarget);}catch(err){toast('Não foi possível salvar a imagem: '+err.message);}});
document.addEventListener('dragover',e=>{const zone=e.target.closest('#cxUploadDrop');if(zone){e.preventDefault();zone.classList.add('dragging');}});
document.addEventListener('dragleave',e=>{e.target.closest('#cxUploadDrop')?.classList.remove('dragging');});
document.addEventListener('drop',async e=>{const zone=e.target.closest('#cxUploadDrop');if(!zone)return;e.preventDefault();zone.classList.remove('dragging');try{await processProfileImage(e.dataTransfer?.files?.[0],state.uploadTarget);}catch(err){toast(err.message);}});

// Área de recorte: arraste a foto, ajuste o zoom e só depois confirme.
let cropDrag=null;
document.addEventListener('pointerdown',e=>{if(e.target.id!=='cxCropCanvas'||!cropState)return;const rect=e.target.getBoundingClientRect();cropDrag={id:e.pointerId,x:e.clientX,y:e.clientY,dx:cropState.dx,dy:cropState.dy,scale:e.target.width/rect.width};e.target.setPointerCapture(e.pointerId);});
document.addEventListener('pointermove',e=>{if(!cropDrag||cropDrag.id!==e.pointerId||!cropState)return;cropState.dx=cropDrag.dx+(e.clientX-cropDrag.x)*cropDrag.scale;cropState.dy=cropDrag.dy+(e.clientY-cropDrag.y)*cropDrag.scale;drawCrop();});
document.addEventListener('pointerup',e=>{if(cropDrag?.id===e.pointerId)cropDrag=null;});
document.addEventListener('pointercancel',()=>{cropDrag=null;});
document.addEventListener('change',e=>{if(e.target.matches('select[data-v3-legacy="interfaceLanguage"]')){const language=e.target.value;updateSetting('interfaceLanguage',language).then(()=>{state.realSettings.interfaceLanguage=language;mount();});}},true);
// Clicar fora dos menus fecha a janelinha. Ícones continuam alternando normalmente.
document.addEventListener('pointerdown',e=>{
 if(state.noticeOpen&&!e.target.closest('#noticePopover,[data-action="notifications"]')){state.noticeOpen=false;refreshNotices();}
 if(state.localeOpen&&!e.target.closest('.cx-locale-pop,[data-action="quick-locale"]')){state.localeOpen=false;const pop=$('.cx-locale-pop');if(pop)pop.hidden=true;}
},true);
document.addEventListener('input',e=>{if(e.target.id==='cxVolume'){const label=document.querySelector('#cxVolumeLabel');if(label)label.textContent=e.target.value+'%';setUiSoundVolume(e.target.value);}if(e.target.id==='cxCropZoom'&&cropState){cropState.zoom=Number(e.target.value)||1;drawCrop();}});
installUiAudio({enabled:()=>state.ui.sound!==false,theme:()=>state.preset});

// Keep keyboard focus inside the module confirmation dialog.
document.addEventListener('keydown',e=>{
 if(e.key!=='Tab'||!state.moduleDialog)return;
 const nodes=$$('.cx-module-dialog button:not([disabled]),.cx-module-dialog input:not([disabled]),.cx-module-dialog [tabindex="0"]').filter(n=>n.getClientRects().length);
 if(!nodes.length)return;
 const first=nodes[0],last=nodes.at(-1);
 if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}
 else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}
});
